"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4: the official VoxTurn's own five answers on every decision window (L2 features; references of plan 6.5).

The official VoxTurn (frozen, exact mode) answers eot, resume, state4, intent and invalid on the 8 s window, phrasing 0.
Text input as VoxTurn documents it (README: "optional transcript of the user's words"; with audio it keeps 64 tokens):
the Whisper-small transcript of the line that just ended at the point, empty when nobody has just spoken. Marker
"[Agent is speaking]" while the assistant talks, else "[User is speaking]" (as L1).
Changed on 2026-11-15 before any system used these answers: the first run gave VoxTurn the last 64 tokens of the
situation text (detected-sound lines and speaker phrases, a format it was not trained on); on dev it then judged a
finished question finished (P >= 0.8) only 20% of the time (floor D) and an ordinary interruption an interruption only
49% (data/p1v4/runs/voxturn_first/).
Output: option probabilities in the order of questions.json, JSON {point id: [p, ...]} with "_columns".
usage: python -X utf8 scripts/p1v4_voxturn.py train|dev <out.json>
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import l1_voxturn  # noqa: E402
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_l1 as L1  # noqa: E402

QUESTIONS = ["eot", "resume", "state4", "intent", "invalid"]


def line_words(which):
    """{point id tuple: the Whisper-small transcript of the line that just ended at the point, or ""}."""
    wins, rows = D.load_windows(which)
    ctx = C.Context(which)
    out = {}
    for w in wins:
        r = rows[w["key"]]
        line = r["points"][w["k"]].get("line")
        out[(w["unit"], w["version"], w["k"])] = ctx.point(r, w["k"])[0].get(line, "") if line else ""
    return out


def main(which, out_path):
    D.gpu_guard()
    mod, vt = l1_voxturn.load_official()
    ex, _ = L1.examples(which)
    words = line_words(which)
    print(which, f"{sum(1 for e in ex if words[e['id']])} of {len(ex)} windows with a line transcript", flush=True)
    names = [f"{q}:{lab}" for q in QUESTIONS for lab in vt.questions[q]["labels"]]
    out = {"_columns": names}
    for b, (w, idx) in enumerate(L1.loader(ex, False, 16)):
        idx = idx.tolist()
        n = len(idx)
        lg = vt.logits(w.cuda(non_blocking=True), [True] * n, [words[ex[i]["id"]] for i in idx],
                       [ex[i]["marker"] for i in idx], ["en"] * n, [[(q, 0) for q in QUESTIONS]] * n)
        p = lg.float().softmax(-1).cpu().numpy()
        for j, i in enumerate(idx):
            vals = []
            for k, q in enumerate(QUESTIONS):
                vals += [round(float(x), 6) for x in p[j * len(QUESTIONS) + k, :len(vt.questions[q]["labels"])]]
            out["|".join(map(str, ex[i]["id"]))] = vals
        if (b + 1) % 500 == 0:
            print(f"{(b + 1) * 16}/{len(ex)}", flush=True)
    json.dump(out, open(out_path, "w"))
    print(which, len(out) - 1, "windows;", names)


if __name__ == "__main__":
    main(*sys.argv[1:3])
